insert into public.part_catalog
 (part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,application_type,application_evidence,application_source_url,compatible_models)
values
('4P-9075','Cat Single Port Metering Fuel Injector','Cat Unit Injector for Engines Fuel Injection Pumps; length 12.3 in, height 4.8 in. CAT explicitly lists Marine Engine 3508/3516/3512 and generator/industrial/petroleum engine groups.',ARRAY['3508','3516','3512'],'سیستم سوخت‌رسانی - انژکتور تک‌پورت','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/4P-9075','Exact Cat page identifies Single Port Metering Fuel Injector, dimensions 12.3 × 4.8 in. Marine Engine 3508/3516/3512 listed. Cat Reman 0R-3051 appears as a separate alternate reman option; not an asserted universal interchange.','REFERENCE','BOTH','CAT Compatible Models explicitly lists Marine Engine 3508/3516/3512 and non-marine generator/industrial/petroleum classes.','https://parts.cat.com/en/catcorp/product/4P-9075',ARRAY['3508','3516','3512']),
('137-5541','Cat Fuel Priming Pump','41.4 Stroke Per Liter Fuel Priming Pump; length 9.0 in, height 1.5 in. CAT compatible-model list includes C7/C9/C11/C13/C15/C18 and 3400/3300 families in truck-engine and equipment groups; no Marine Engine category appears in retrieved page.',ARRAY['C7','C9','C11','C13','C15','C18','3406E','3406C','3406B','3306C','3306B','3126B','3126E','3208'],'سیستم سوخت‌رسانی - پمپ پرایمینگ','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/137-5541','Exact Cat page identifies 41.4 Stroke Per Liter Fuel Priming Pump, output 41.4 stroke/liter, length 9.0 in, height 1.5 in. Compatible models are listed under truck engine and land equipment groups; no Marine Engine group in retrieved page.','REFERENCE','LAND','CAT Compatible Models lists truck/land machine classes; no Marine Engine category in retrieved page.','https://parts.cat.com/en/catcorp/product/137-5541',ARRAY['C7','C9','C11','C13','C15','C18','3406E','3406C','3406B','3306C','3306B','3126B','3126E','3208']),
('352-0211','Cat Water Pump Group','Water Pump; length 13.0 in, height 8.0 in. CAT explicitly lists Marine Engine C18/C15 and non-marine truck, generator, machine and industrial engine groups.',ARRAY['C18','C15','C16','C-18','C-15','C-16'],'سیستم خنک‌کاری - واترپمپ','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/352-0211','Exact Cat page identifies Water Pump, dimensions 13.0 × 8.0 in. Marine Engine C18/C15 explicitly listed. Cat Reman 10R-0484 is shown as a separate reman water pump for C15/C16; no direct interchange is asserted.','REFERENCE','BOTH','CAT Compatible Models explicitly lists Marine Engine C18/C15 and non-marine groups.','https://parts.cat.com/en/catcorp/product/352-0211',ARRAY['C18','C15','C16']),
('172-7767','Cat Water Pump used in Engine','Cat Water Pump used in Engine; length 12.1 in, height 9.4 in. Compatible model groups include generator, industrial and land equipment; no Marine Engine group in retrieved page.',ARRAY['3306','3304','3304B','G3306B'],'سیستم خنک‌کاری - واترپمپ','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/172-7767','Exact Cat search result identifies Water Pump used in Engine, dimensions 12.1 × 9.4 in, with generator/industrial/land model classes. Retrieved page timed out before product image could be extracted; reference-only.','REFERENCE','LAND','CAT Compatible Models lists generator/industrial and land machine classes; no Marine Engine group in retrieved result.','https://parts.cat.com/en/catcorp/product/172-7767',ARRAY['3306','3304','3304B','G3306B']),
('352-0206','Cat Water Pump Group','Water Pump; length 9.4 in, height 12.1 in. Compatible model groups include C11/C13 truck and industrial engines, C13 generator set, AD22 and land equipment; no Marine Engine group.',ARRAY['C11','C13'],'سیستم خنک‌کاری - واترپمپ','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/352-0206','Exact Cat page identifies Water Pump, dimensions 9.4 × 12.1 in. Compatible models include C11/C13, AD22 and equipment; no Marine Engine group in retrieved page.','REFERENCE','LAND','CAT Compatible Models lists truck/industrial and land equipment groups; no Marine Engine group.','https://parts.cat.com/en/catcorp/product/352-0206',ARRAY['C11','C13']),
('350-0666','Cat Hydraulic Piston Pump','Cat Hydraulic Piston Pump; length 12.6 in, height 6.7 in; compatible models 414E/416E/434E/422E/428E backhoe loaders. Cat Reman 20R-4693 is displayed as a separate alternate product.',ARRAY['414E','416E','434E','422E','428E'],'هیدرولیک - پمپ پیستونی','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/350-0666','Exact Cat page identifies Hydraulic Piston Pump, dimensions 12.6 × 6.7 in and Backhoe Loader 414E/416E/434E/422E/428E compatible group. Cat Reman 20R-4693 is a separate alternate; no direct interchange inferred.','REFERENCE','LAND','CAT Compatible Models lists Backhoe Loader models only.','https://parts.cat.com/en/catcorp/product/350-0666',ARRAY['414E','416E','434E','422E','428E']),
('2W-9978','Cat Transmission Oil Cooler Core','Shell-and-tube oil-to-water Transmission Oil Cooler Core. CAT compatible models include Marine Engine 3196/C12 and land truck, grader, loader, tractor and industrial engine groups.',ARRAY['3196','C12','C-12','3306C','3306B','3306','1673C'],'سیستم خنک‌کاری - کولر روغن گیربکس','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/2W-9978','Exact Cat page identifies Transmission Oil Cooler Core, shell-and-tube oil-to-water type. Marine Engine 3196/C-12/C12 explicitly listed, plus multiple non-marine equipment/engine classes. Cat Reman 0R-5515 is displayed as a separate alternate oil cooler.','REFERENCE','BOTH','CAT Compatible Models explicitly lists Marine Engine 3196/C-12/C12 and non-marine classes.','https://parts.cat.com/en/catcorp/product/2W-9978',ARRAY['3196','C12','C-12']),
('8J-6730','Cat Axial Piston Pump Fixed Displacement','Cat Axial Piston Pump Fixed Displacement; Cat Parts Store page marks this part DISCONTINUED and says contact dealer for replacement options. Compatible model list shows 120G motor grader only.',ARRAY['120G'],'هیدرولیک - پمپ پیستونی','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/8J-6730','Exact Cat Parts Store page marks 8J-6730 DISCONTINUED. 10R-2438 Cat Reman appears as a replacement/alternate option; do not treat as direct replacement without dealer confirmation. No public saleable product created.','REFERENCE','LAND','CAT page lists 120G motor grader and marks the part discontinued.','https://parts.cat.com/en/catcorp/product/8J-6730',ARRAY['120G'])
insert into public.products
 (sku,name,brand,category,machine_model,description,image_url,price_usd,price_irr,stock,status,application_type,application_evidence,application_source_url)
values
('CAT-4P-9075','انژکتور تک‌پورت Cat 4P-9075','Caterpillar','قطعات موتور - کاربرد مشترک دریا و خشکی','3508، 3516، 3512','Cat Single Port Metering Fuel Injector؛ طول 12.3 اینچ و ارتفاع 4.8 اینچ. CAT گروه Marine Engine 3508/3516/3512 را فهرست می‌کند. Cat Reman 0R-3051 گزینه بازسازی‌شده جداگانه است. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/C10869416?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat page lists Marine Engine 3508/3516/3512 and non-marine generator/industrial/petroleum classes.','https://parts.cat.com/en/catcorp/product/4P-9075'),
('CAT-137-5541','پمپ هواگیری و پرایمینگ سوخت Cat 137-5541','Caterpillar','قطعات موتور','C7، C9، C11، C13، C15، C18، 3406 و 3306','Cat 41.4 Stroke Per Liter Fuel Priming Pump؛ دبی عملکرد 41.4 stroke/liter، طول 9 اینچ و ارتفاع 1.5 اینچ. در صفحه رسمی گروه Marine Engine جداگانه درج نشده است. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20180213-33539-27894?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','LAND','Exact Cat page lists truck/land machine classes; no Marine Engine category in retrieved page.','https://parts.cat.com/en/catcorp/product/137-5541'),
('CAT-352-0211','واترپمپ Cat 352-0211','Caterpillar','قطعات موتور - کاربرد مشترک دریا و خشکی','C18، C15، C16 و ماشین‌آلات منتخب','Cat Water Pump؛ طول 13 اینچ و ارتفاع 8 اینچ. CAT گروه Marine Engine C18/C15 و کاربردهای غیر دریایی را فهرست می‌کند. Cat Reman 10R-0484 گزینه جداگانه بازسازی‌شده است. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/C10539024?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat page lists Marine Engine C18/C15 and non-marine groups.','https://parts.cat.com/en/catcorp/product/352-0211'),
('CAT-352-0206','واترپمپ Cat 352-0206','Caterpillar','قطعات موتور','C11، C13، AD22 و ماشین‌آلات منتخب','Cat Water Pump؛ طول 9.4 اینچ و ارتفاع 12.1 اینچ. CAT گروه‌های Truck/Industrial Engine و ماشین‌آلات را فهرست می‌کند؛ گروه Marine Engine مشاهده نشد. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/C10539028?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','LAND','Exact Cat page lists truck/industrial and land equipment groups; no Marine Engine group.','https://parts.cat.com/en/catcorp/product/352-0206'),
('CAT-350-0666','پمپ پیستونی هیدرولیک Cat 350-0666','Caterpillar','قطعات هیدرولیک','414E، 416E، 434E، 422E، 428E','Cat Hydraulic Piston Pump؛ طول 12.6 اینچ و ارتفاع 6.7 اینچ. CAT سازگاری را برای خانواده Backhoe Loader اعلام می‌کند. Cat Reman 20R-4693 گزینه جداگانه است. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20200310-9212b-938ae?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','LAND','Exact Cat page lists Backhoe Loader models 414E/416E/434E/422E/428E.','https://parts.cat.com/en/catcorp/product/350-0666'),
('CAT-2W-9978','کولر روغن گیربکس Cat 2W-9978','Caterpillar','قطعات موتور - کاربرد مشترک دریا و خشکی','3196، C12 و ماشین‌آلات منتخب','Cat Transmission Oil Cooler Core؛ مبدل Shell-and-Tube روغن به آب. CAT گروه Marine Engine 3196/C12 و گروه‌های غیر دریایی را فهرست می‌کند. Cat Reman 0R-5515 گزینه جداگانه است. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20200812-4e0ae-1c6b4?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat page lists Marine Engine 3196/C12 and non-marine equipment/engine groups.','https://parts.cat.com/en/catcorp/product/2W-9978')
